(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-066":{scenario:{company:"Northpine Credit Tech",supervisor:{name:"Lương Khánh An",role:{vi:"Trưởng nhóm Nền tảng Học máy",en:"ML Platform Lead"}},ref_code:"MLD-0664",title:{vi:"Triển khai bản đã duyệt. Đủ năng lực cao điểm. Không sửa tắt.",en:"Ship the approved model. Size for peak. No hot fixes."},brief:{vi:"Bạn chuẩn bị triển khai dịch vụ chấm điểm gian lận giao dịch MLD-0664 lên Kubernetes. Sổ đăng ký: fraud-v15 là bản mới nhất nhưng trượt cổng đánh giá; fraud-v14 đã được Hội đồng rủi ro mô hình phê duyệt. Cao điểm dự kiến 1.800 yêu cầu/giây; mỗi replica xử lý tối đa 150 yêu cầu/giây mà vẫn đạt SLO p95; mục tiêu sử dụng 70%. Đối chiếu manifest nháp với phiếu thay đổi đã duyệt, sửa phiên bản mô hình và số replica, rồi lập báo cáo có căn cứ.",en:"You are preparing to deploy transaction fraud scoring service MLD-0664 on Kubernetes. Registry: fraud-v15 is the latest but failed the evaluation gate; fraud-v14 was approved by the model risk committee. Expected peak is 1,800 requests/second; each replica handles at most 150 requests/second within the p95 SLO; target utilisation is 70%. Compare the draft manifest with the approved change ticket, fix the model version and replica count, then write an evidence-based report."},reference_title:{vi:"Phiếu thay đổi & sổ đăng ký đã duyệt · MLD-0664",en:"Approved change ticket & registry · MLD-0664"},fields:[{id:"MODEL_VER",label:{vi:"Phiên bản mô hình triển khai",en:"Deployed model version"},initial:"fraud-v15",expected:"fraud-v14",choices:["fraud-v13","fraud-v14","fraud-v15"],reference:"Sổ đăng ký mô hình",hint:{vi:"Chỉ phiên bản ở trạng thái đã phê duyệt mới được phục vụ production; bản mới nhất chưa chắc đã được duyệt.",en:"Only an approved version may serve production; the newest build is not necessarily approved."}},{id:"REPLICAS",label:{vi:"Số replica tối thiểu",en:"Minimum replicas"},initial:"12",expected:"18",reference:"Phiếu tính năng lực phục vụ",ref_value:{vi:"Cao điểm 1.800 yêu cầu/giây; 150 yêu cầu/giây mỗi replica; mục tiêu sử dụng 70%",en:"Peak 1,800 requests/s; 150 requests/s per replica; target utilisation 70%"},hint:{vi:"Năng lực mỗi replica phải nhân với mức sử dụng mục tiêu để chừa dự phòng, rồi làm tròn lên.",en:"Multiply per-replica capacity by target utilisation to keep headroom, then round up."}}],sop32:{vi:"Số replica = làm tròn lên (lưu lượng cao điểm / (năng lực mỗi replica x mức sử dụng mục tiêu)); không triển khai phiên bản chưa ở trạng thái Approved trong sổ đăng ký.",en:"Replicas = round up (peak traffic / (per-replica capacity x target utilisation)); never deploy a version that is not Approved in the registry."},context:{label:"MODEL SERVING / MLD-0664",metrics:[{label:{vi:"Cao điểm dự kiến",en:"Expected peak"},value:"1,800 RPS"},{label:{vi:"Năng lực mỗi replica",en:"Capacity per replica"},value:"150 RPS"},{label:{vi:"Mục tiêu sử dụng",en:"Target utilisation"},value:"70%"}]},crisis:{vi:"Trưởng nhóm sản phẩm nhắn: “Tỷ lệ chặn giao dịch đang cao, vào thẳng pod production sửa ngưỡng mô hình từ 0,5 lên 0,8 bằng kubectl exec đi, khỏi mở phiếu thay đổi, khỏi qua pipeline. Tối nay phải xong.”",en:"The product lead messages you: “The block rate is too high. Exec into the production pod and change the model threshold from 0.5 to 0.8, skip the change ticket and the pipeline. It must be done tonight.”"},options:{safe:{vi:"Từ chối sửa trực tiếp trên production; báo trưởng nhóm nền tảng và chủ sở hữu mô hình, mở thay đổi khẩn cấp, đổi ngưỡng qua cấu hình có phê duyệt, kiểm thử, canary và lưu vết.",en:"Refuse to edit production directly; inform the platform lead and model owner, raise an emergency change and adjust the threshold via approved config with testing, canary and an audit trail."},shortcut:{vi:"Vào pod sửa ngưỡng ngay cho tỷ lệ chặn giảm, mai bổ sung phiếu thay đổi sau.",en:"Exec into the pod and change the threshold now, then file the change ticket tomorrow."},wait:{vi:"Không làm gì, chờ trưởng nhóm sản phẩm tự tìm người khác sửa.",en:"Do nothing and wait for the product lead to find someone else."}},questions:{vi:["Vì sao phải triển khai fraud-v14 với 18 replica? Bạn dựa vào sổ đăng ký, kết quả kiểm thử tải và công thức nào?","Khi bị yêu cầu sửa ngưỡng mô hình trực tiếp trên production không qua quy trình thay đổi, bạn kiểm soát rủi ro và lưu vết thế nào?"],en:["Why deploy fraud-v14 with 18 replicas? Which registry entry, load test result and formula support you?","When asked to change the model threshold directly in production without change control, how do you manage the risk and keep an audit trail?"]},hints:{vi:["Đọc trạng thái từng phiên bản trong sổ đăng ký thay vì tin vào tag latest.","Tính năng lực hiệu dụng của một replica rồi áp công thức ở SOP mục 3.2, nhớ làm tròn lên.","Đọc lại SOP mục 4.2: mọi thay đổi trên production đi qua pipeline và phiếu thay đổi, kể cả thay đổi khẩn cấp."],en:["Read each version's status in the registry instead of trusting the latest tag.","Work out one replica's effective capacity, apply the SOP 3.2 formula and round up.","Re-read SOP 4.2: every production change goes through the pipeline and a change ticket, emergencies included."]},terminal:{system:"mlops-ctl",settable:["MODEL_VER","REPLICAS"],commands:[{cmd:"status",out:{vi:"Triển khai MLD-0664: PENDING | manifest dùng tag latest -> fraud-v15 | replicas 12 | kiểm tra trước triển khai: 2 cảnh báo.",en:"Deployment MLD-0664: PENDING | manifest uses tag latest -> fraud-v15 | replicas 12 | pre-deploy checks: 2 warnings."}},{cmd:"cat registry.txt",out:{vi:"fraud-v13: Archived | fraud-v14: Approved (Hội đồng rủi ro mô hình) | fraud-v15: Rejected - tỷ lệ báo động nhầm ở nhóm khách trên 60 tuổi vượt ngưỡng.",en:"fraud-v13: Archived | fraud-v14: Approved (model risk committee) | fraud-v15: Rejected - false alarm rate for customers over 60 above limit."}},{cmd:"cat loadtest.txt",out:{vi:"1 replica (4 vCPU): 150 RPS cho p95 = 85 ms (SLO 100 ms); ở 180 RPS p95 tăng lên 240 ms.",en:"1 replica (4 vCPU): 150 RPS gives p95 = 85 ms (SLO 100 ms); at 180 RPS p95 rises to 240 ms."}},{cmd:"cat change_ticket.md",out:{vi:"CHG-0664 đã duyệt: phục vụ fraud-v14, cao điểm 1.800 RPS, mục tiêu sử dụng 70%, canary 10% trong 30 phút trước khi lên 100%.",en:"CHG-0664 approved: serve fraud-v14, peak 1,800 RPS, target utilisation 70%, 10% canary for 30 minutes before 100%."}},{cmd:"kubectl get hpa",out:{vi:"fraud-svc: minReplicas 12, maxReplicas 30, mục tiêu CPU 70% - giá trị tối thiểu lấy theo bản nháp.",en:"fraud-svc: minReplicas 12, maxReplicas 30, CPU target 70% - minimum taken from the draft."}}]}},learning:{summary:{vi:"Kỹ sư học máy và vận hành mô hình (MLOps) đưa mô hình từ phòng thí nghiệm vào production một cách tin cậy: đóng gói, tự động hóa huấn luyện, kiểm định, triển khai, giám sát và quay lui. Họ xây nền tảng CI/CD cho mô hình, sổ đăng ký mô hình, kho đặc trưng và hệ thống giám sát trôi dữ liệu. Nghề đòi hỏi kỹ thuật phần mềm, hạ tầng đám mây, Kubernetes, hiểu học máy và kỷ luật quản lý thay đổi.",en:"A machine learning engineer in MLOps takes models from the lab into production reliably: packaging, automating training, validation, deployment, monitoring and rollback. They build model CI/CD, the model registry, feature stores and drift monitoring. The role requires software engineering, cloud infrastructure, Kubernetes, machine learning understanding and change management discipline."},responsibilities:{vi:["Xây pipeline CI/CD/CT tự động huấn luyện, kiểm định và đóng gói mô hình.","Quản lý sổ đăng ký mô hình, phiên bản dữ liệu, đặc trưng và quy trình phê duyệt.","Triển khai dịch vụ suy luận với canary, blue-green, tự động co giãn và quay lui.","Giám sát độ trễ, lỗi, trôi dữ liệu, trôi khái niệm và hiệu năng mô hình sau triển khai.","Bảo đảm bảo mật, chi phí hạ tầng, lưu vết và tuân thủ quản trị rủi ro mô hình."],en:["Build CI/CD/CT pipelines that automatically train, validate and package models.","Manage the model registry, data and feature versions and the approval workflow.","Deploy inference services with canary, blue-green, autoscaling and rollback.","Monitor latency, errors, data drift, concept drift and model performance after release.","Ensure security, infrastructure cost control, audit trails and model risk compliance."]},competencies:[{name:{vi:"Hạ tầng & Kubernetes",en:"Infrastructure & Kubernetes"},desc:{vi:"Đóng gói container, cấu hình tài nguyên, tự động co giãn và mạng cho dịch vụ suy luận.",en:"Containerise, set resources, autoscaling and networking for inference services."}},{name:{vi:"Tự động hóa pipeline ML",en:"ML pipeline automation"},desc:{vi:"Biến notebook thành pipeline tái lập được, có kiểm thử dữ liệu và kiểm định mô hình.",en:"Turn notebooks into reproducible pipelines with data tests and model validation."}},{name:{vi:"Giám sát mô hình",en:"Model monitoring"},desc:{vi:"Theo dõi trôi dữ liệu, hiệu năng theo nhóm và đặt cảnh báo kích hoạt huấn luyện lại.",en:"Track drift and per-group performance and set alerts that trigger retraining."}},{name:{vi:"Hoạch định năng lực",en:"Capacity planning"},desc:{vi:"Từ kiểm thử tải tính số replica, chừa dự phòng để giữ SLO lúc cao điểm.",en:"Size replicas from load tests with headroom to hold the SLO at peak."}},{name:{vi:"Quản lý thay đổi & tuân thủ",en:"Change control & compliance"},desc:{vi:"Mọi thay đổi qua pipeline, phiếu thay đổi và phê duyệt; không sửa tắt trên production.",en:"Every change goes through the pipeline, a ticket and approval; no direct production edits."}}],knowledge:{vi:["Thực hành MLOps: CI/CD/CT, sổ đăng ký mô hình, kho đặc trưng, tái lập thí nghiệm.","Chiến lược triển khai: shadow, canary, blue-green, A/B và quay lui tự động.","Giám sát: trôi dữ liệu (PSI, kiểm định KS), trôi khái niệm, độ lệch giữa huấn luyện và phục vụ.","Kubernetes: Deployment, HPA, giới hạn tài nguyên; SLO độ trễ p95/p99 và hoạch định năng lực.","ITIL 4 về quản lý thay đổi (tiêu chuẩn, thông thường, khẩn cấp); model card và ISO/IEC 42001."],en:["MLOps practice: CI/CD/CT, model registry, feature store and reproducible experiments.","Deployment strategies: shadow, canary, blue-green, A/B and automated rollback.","Monitoring: data drift (PSI, KS test), concept drift and training-serving skew.","Kubernetes: Deployments, HPA and resource limits; p95/p99 latency SLOs and capacity planning.","ITIL 4 change enablement (standard, normal, emergency); model cards and ISO/IEC 42001."]},tools:["Docker & Kubernetes","MLflow","Kubeflow / Airflow","Prometheus & Grafana","Terraform","Python"],tools_en:["Docker & Kubernetes","MLflow","Kubeflow / Airflow","Prometheus & Grafana","Terraform","Python"],kpis:{vi:["Tỷ lệ triển khai thành công không phải quay lui.","Thời gian từ khi mô hình được duyệt đến khi chạy production.","Mức tuân thủ SLO độ trễ p95 và tỷ lệ lỗi của dịch vụ suy luận.","Thời gian phát hiện trôi dữ liệu và kích hoạt huấn luyện lại."],en:["Share of deployments with no rollback.","Lead time from model approval to production.","p95 latency SLO compliance and inference error rate.","Time to detect drift and trigger retraining."]},day:[{time:"08:30",vi:"Xem dashboard độ trễ, lỗi và trôi dữ liệu của các mô hình đang chạy.",en:"Review latency, error and drift dashboards for live models."},{time:"10:00",vi:"Rà soát pull request pipeline huấn luyện, kiểm tra bước kiểm định tự động.",en:"Review a training pipeline pull request and its automated validation step."},{time:"13:30",vi:"Chạy kiểm thử tải cho phiên bản mô hình mới, ghi lại năng lực mỗi replica.",en:"Load test a new model version and record per-replica capacity."},{time:"15:00",vi:"Triển khai canary 10% theo phiếu thay đổi, theo dõi chỉ số trước khi mở rộng.",en:"Run a 10% canary per the change ticket and watch metrics before scaling out."},{time:"17:00",vi:"Cập nhật runbook quay lui và ghi chú bàn giao cho ca trực.",en:"Update the rollback runbook and handover notes for on-call."}],mistakes:{vi:["Triển khai theo tag latest thay vì phiên bản đã phê duyệt trong sổ đăng ký.","Tính replica theo năng lực tối đa, không chừa dự phòng nên vỡ SLO lúc cao điểm.","Sửa cấu hình, ngưỡng trực tiếp trên production không qua pipeline và phiếu thay đổi."],en:["Deploying the latest tag instead of the approved registry version.","Sizing replicas at maximum capacity without headroom, breaking the SLO at peak.","Editing config or thresholds directly in production, bypassing the pipeline and change ticket."]},career:[{vi:"Kỹ sư ML / DevOps tập sự",en:"Junior ML / DevOps engineer"},{vi:"Kỹ sư MLOps",en:"MLOps engineer"},{vi:"Kỹ sư nền tảng học máy cấp cao",en:"Senior ML platform engineer"},{vi:"Kiến trúc sư / trưởng nền tảng học máy",en:"ML platform architect / head of ML platform"}],glossary:[{term:"Model registry",vi:"Kho quản lý phiên bản mô hình kèm siêu dữ liệu, kết quả đánh giá và trạng thái phê duyệt.",en:"Store of model versions with metadata, evaluation results and approval status."},{term:"Canary deployment",vi:"Chuyển một phần nhỏ lưu lượng sang phiên bản mới để theo dõi trước khi mở rộng.",en:"Routing a small share of traffic to a new version to watch it before scaling out."},{term:"Data drift",vi:"Phân bố dữ liệu đầu vào thay đổi so với lúc huấn luyện, có thể làm mô hình suy giảm.",en:"Input data distribution shifting from training time, which can degrade the model."},{term:"Training-serving skew",vi:"Sai khác giữa cách tạo đặc trưng lúc huấn luyện và lúc phục vụ.",en:"Mismatch between how features are built in training and in serving."},{term:"HPA",vi:"Bộ tự động co giãn số pod của Kubernetes theo CPU, bộ nhớ hoặc chỉ số tùy chỉnh.",en:"Kubernetes autoscaler that adjusts pod count by CPU, memory or custom metrics."}],quiz:[{q:{vi:"Cao điểm 2.400 yêu cầu/giây, mỗi replica đạt SLO ở 200 yêu cầu/giây, mục tiêu sử dụng 60%. Cần tối thiểu bao nhiêu replica?",en:"Peak is 2,400 requests/s, each replica meets the SLO at 200 requests/s and target utilisation is 60%. How many replicas at minimum?"},options:{vi:["12 replica","20 replica","14 replica","24 replica"],en:["12 replicas","20 replicas","14 replicas","24 replicas"]},answer:1,explain:{vi:"2.400 / (200 x 0,6) = 20 replica; tính theo 200 yêu cầu/giây sẽ chỉ ra 12 và không còn dự phòng.",en:"2,400 / (200 x 0.6) = 20 replicas; sizing at 200 requests/s gives 12 with no headroom."}},{q:{vi:"Chiến lược nào chuyển một phần nhỏ lưu lượng thật sang phiên bản mới để theo dõi trước khi mở rộng?",en:"Which strategy routes a small share of real traffic to a new version to watch it before scaling out?"},options:{vi:["Big-bang","Recreate","Shadow","Canary"],en:["Big-bang","Recreate","Shadow","Canary"]},answer:3,explain:{vi:"Canary phục vụ thật một phần nhỏ người dùng; shadow chỉ sao chép lưu lượng mà không trả kết quả cho người dùng.",en:"Canary truly serves a small share of users; shadow only mirrors traffic without returning results."}},{q:{vi:"Bạn được yêu cầu sửa ngưỡng mô hình trực tiếp trong pod production, không mở phiếu thay đổi. Bạn làm gì?",en:"You are asked to change the model threshold directly in a production pod without a change ticket. What do you do?"},options:{vi:["Từ chối sửa trực tiếp, mở thay đổi khẩn cấp có phê duyệt, triển khai qua pipeline và canary","Sửa ngay bằng kubectl exec","Sửa rồi xóa lịch sử lệnh","Tắt mô hình để không chặn giao dịch nào"],en:["Refuse direct edits, raise an approved emergency change, deploy via pipeline and canary","Edit it now with kubectl exec","Edit it and clear the command history","Turn the model off so nothing is blocked"]},answer:0,explain:{vi:"Thay đổi khẩn cấp vẫn cần phê duyệt và lưu vết; sửa tắt làm mất khả năng kiểm soát, quay lui và kiểm toán.",en:"Emergency changes still need approval and records; hot fixes destroy control, rollback and auditability."}},{q:{vi:"PSI của một đặc trưng đầu vào là 0,31. Theo quy ước thực hành phổ biến, điều này nghĩa là gì?",en:"A feature's PSI is 0.31. Under the common rule of thumb, what does it mean?"},options:{vi:["Ổn định, không cần làm gì","Trôi nhẹ, chỉ cần theo dõi","Trôi đáng kể, cần điều tra và cân nhắc huấn luyện lại","Mô hình chắc chắn đã sai"],en:["Stable, no action needed","Slight drift, just monitor","Significant drift, investigate and consider retraining","The model is certainly wrong"]},answer:2,explain:{vi:"Quy ước thường dùng: dưới 0,1 ổn định, 0,1 đến 0,25 trôi vừa, trên 0,25 trôi đáng kể.",en:"Common rule: below 0.1 stable, 0.1 to 0.25 moderate drift, above 0.25 significant drift."}}]}}})})(window.KKR);
